// URL Shortener — core encode/decode + read/write paths
const BASE62 = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

// Encode a numeric auto-increment ID to a 6-character Base62 string
function encodeBase62(num) {
  if (num === 0) return BASE62[0].repeat(6);
  let result = '';
  while (num > 0) {
    result = BASE62[num % 62] + result;
    num = Math.floor(num / 62);
  }
  return result.padStart(6, BASE62[0]); // always exactly 6 chars
}

// Decode a Base62 string back to the numeric ID (for debugging/analytics)
function decodeBase62(str) {
  return str.split('').reduce((acc, ch) => acc * 62 + BASE62.indexOf(ch), 0);
}

// WRITE PATH — create a short code for a long URL
async function shortenUrl(longUrl, db, cache) {
  // 1. Insert into DB to get a guaranteed-unique auto-increment ID
  const { rows } = await db.query(
    `INSERT INTO url_mappings (long_url, created_at)
     VALUES ($1, NOW()) RETURNING id`,
    [longUrl]
  );
  const id = rows[0].id;
  const code = encodeBase62(id);

  // 2. Write the code back (could also compute code in app and store immediately)
  await db.query(
    'UPDATE url_mappings SET code = $1 WHERE id = $2',
    [code, id]
  );

  // 3. Warm the cache — avoid a cold-start miss on the first redirect
  await cache.set(`url:${code}`, longUrl, { EX: 86400 }); // 24h TTL
  return code;
}

// READ PATH — resolve a short code to the long URL (cache-first)
async function resolveCode(code, db, cache) {
  // 1. Check Redis — ~1ms round-trip, no DB load
  const cached = await cache.get(`url:${code}`);
  if (cached) return { url: cached, source: 'cache' };

  // 2. Cache miss — query Postgres
  const { rows } = await db.query(
    `SELECT long_url, expires_at
     FROM url_mappings WHERE code = $1`,
    [code]
  );
  if (!rows[0]) return null; // 404

  // 3. Check expiry
  if (rows[0].expires_at && rows[0].expires_at < new Date()) {
    return null; // 410 Gone
  }

  // 4. Backfill cache so next request hits Redis
  await cache.set(`url:${code}`, rows[0].long_url, { EX: 3600 });
  return { url: rows[0].long_url, source: 'db' };
}

// News Feed — hybrid fan-out implementation
const CELEBRITY_THRESHOLD = 1_000_000; // followers
const FEED_MAX_SIZE = 1000;             // items per user in Redis

// WRITE PATH — called when any user publishes a post
async function publishPost(authorId, postId, db, redis) {
  // Get the author's follower count to decide fan-out strategy
  const { rows: [author] } = await db.query(
    'SELECT follower_count FROM users WHERE id = $1',
    [authorId]
  );

  if (author.follower_count >= CELEBRITY_THRESHOLD) {
    // Celebrity: skip fan-out entirely — followers pull at read time
    // Just write the post to the posts table (already done by caller)
    return;
  }

  // Normal user: fan out to all followers' feed lists in Redis
  // Paginate follower fetch for users with 100k+ followers
  let offset = 0;
  const BATCH = 5000;
  const timestamp = Date.now();

  while (true) {
    const { rows } = await db.query(
      `SELECT follower_id FROM follows
       WHERE followee_id = $1 LIMIT $2 OFFSET $3`,
      [authorId, BATCH, offset]
    );
    if (rows.length === 0) break;

    const pipeline = redis.pipeline();
    for (const { follower_id } of rows) {
      // ZADD with timestamp as score — sorted set auto-sorts by recency
      pipeline.zadd(`feed:${follower_id}`, timestamp, postId);
      // Trim to last FEED_MAX_SIZE entries to bound memory usage
      pipeline.zremrangebyrank(`feed:${follower_id}`, 0, -(FEED_MAX_SIZE + 1));
    }
    await pipeline.exec();
    offset += BATCH;
  }
}

// READ PATH — assemble a paginated feed for a user
async function getFeed(userId, page, limit, db, redis) {
  const start = page * limit;
  const end = start + limit - 1;

  // 1. Fetch pre-computed post IDs from the user's feed sorted set
  const postIds = await redis.zrevrange(`feed:${userId}`, start, end);

  // 2. Identify celebrities the user follows — these were NOT fanned-out
  const { rows: celebrities } = await db.query(
    `SELECT u.id FROM follows f
     JOIN users u ON u.id = f.followee_id
     WHERE f.follower_id = $1
       AND u.follower_count >= $2`,
    [userId, CELEBRITY_THRESHOLD]
  );

  // 3. Pull recent posts from celebrity accounts (limit to last 50 each)
  const celebPostIds = [];
  for (const { id: celebId } of celebrities) {
    const { rows } = await db.query(
      `SELECT id FROM posts WHERE author_id = $1
       ORDER BY created_at DESC LIMIT 50`,
      [celebId]
    );
    celebPostIds.push(...rows.map(r => r.id));
  }

  // 4. Merge, deduplicate, and sort by timestamp (simplified here)
  const allIds = [...new Set([...postIds, ...celebPostIds])];

  // 5. Hydrate post content from post cache or DB
  return hydratePostContent(allIds.slice(0, limit), redis, db);
}
